  createAndSave(pdf, idDocumento) {
    this.savePDF(pdf, idDocumento)
    this.print(pdf)
  }

  async print(pdf) {
    await pdf.getBlob((data) => {
      const fileURL = window.URL.createObjectURL(data)
      printJS(fileURL)
    })
  }

  /**Mi converto il file in base64 e lo salvo sul server */
  savePDF(pdf, idDocumento, idVisita=null) {
    pdf.getBase64((file) => {
      this.saveToServer(file, idDocumento, idVisita)
    })
  }

  async getPDFBase64Text(pdfDoc) {
    let b64

    await pdfDoc.getBase64((data) => {
      b64 = data
    })
    return b64
  }

  async saveToServer(file, idDocumento, idVisita=null) {
    this.fileBase64 = file

    const obj = {
      filebase64: file,
      idDocumento: idDocumento,
    }
    await this.service.postCallRequest({ action: 'saveFileReport', param: obj })

    if (this.appGen.configLinfa.InvioRefertiSenzaFirma === true) {
      await firstValueFrom(this.visitaServ.matchtiporichiesta(idVisita))
    }
  }

