  /**Genera il referto */

  createReferto(data, bozza, kcalNascoste = false) {
    // alert('crea referto')
    let pdf

    this.visitaId =
      data && data.visita && data.visita.idVisita ? data.visita.idVisita : null
    switch (data.visita.idTipoPrestazione) {
      case TipoPrestazione.VisitaControllo:
        pdf = this.generatePdf(
          this.createBodyVisitaControllo(data, kcalNascoste),

          bozza
        )
        break

      case TipoPrestazione.PrimaVisita:
        pdf = this.generatePdf(
          this.createBody(data, kcalNascoste),

          bozza
        )
        break

      default:
        pdf = this.generatePdf(
          this.createBody(data, kcalNascoste),

          bozza
        )

        break
    }

    return pdf
  }

  /**Genera il referto di una visita di controllo*/
  createRefertoVisitaControllo(data) {
    const pdf = this.generatePdf(this.createBodyVisitaControllo(data))
    pdf.getBase64((file) => {
      this.saveToServer(file, data.idDocumento)
    })
  }

  createBodyPianoNutrizionale(data, kcalNascoste, isDietaSettimanale) {
    const leftColumn = []

    //colonne laterali
    leftColumn.push(this.intestazioneMediciLaterale())

    //colonne centrali come le altre ad esempio anamnesi
    this.getInfoPaziente(data)
    this.getInfoVisita(data)
    if (!this.appGen.isNullOrUndefined(data.tutore)) {
      if (data.tutore.length > 0) {
        this.getTutoriMinorenne(data)
      }
    }
    this.bodyContent.push(this.getValiditaPianoNutrizionaleOrizzontale(data))
    switch (data.visita.idTipoAlimentazione) {
      case this.tipoAlimentazione.Artificiale:
        this.getProdottiArtificiale(data, kcalNascoste)
        if (data.sacche) {
          this.getSaccheTotaliPerGiorni(data)
        }
        this.getNotePianoNutrizionale(data);

        this.getValoriNutrizionali(data, kcalNascoste);

        break
      case this.tipoAlimentazione.NaturaleMista:
        this.getProdottiNaturale(data, false, kcalNascoste, isDietaSettimanale)
        this.getNotePianoNutrizionale(data)

        this.getValoriNutrizionali(data, kcalNascoste)
        break

      default:
        break
    }
    this.bodyContent.push(this.createFooterGenericoFirma(data))
    return this.generateTableBody(leftColumn, this.bodyContent)
  }

/**
 *  Prendo informazioni dalla Anamnesi Alimentare e creo il pdf in bozza
 * @param data
 * @returns
 */
  createBodyAnamnesiAlimentare(data, kcalNascoste, isDietaSettimanale){
    const leftColumn = []

    //colonne laterali
    leftColumn.push(this.intestazioneMediciLaterale())

    //colonne centrali come le altre ad esempio anamnesi
    this.getInfoPaziente(data)
    this.getInfoVisita(data)
    if (!this.appGen.isNullOrUndefined(data.tutore)) {
      if (data.tutore.length > 0) {
        this.getTutoriMinorenne(data)
      }
    }


   this.getAnamnesiAlimentare(data,true, kcalNascoste)
   this.getProdottiNaturale(data, true, kcalNascoste, isDietaSettimanale)
   this.getNotePianoNutrizionale(data)

//this.getValoriNutrizionali(data)


    return this.generateTableBody(leftColumn, this.bodyContent)
  }

  /**Contenuto tabella delle prescrizioni sacche */
  createBodyPrescrizioneSacche(data) {
    const leftColumn = []

    this.getInfoPaziente(data)

    data.prodotti.forEach((element) => {
      this.getSacche(element)
    })

    return this.generateTableBody(leftColumn, this.bodyContent)
  }

