  /** Aggiunte delle sacche parenterali personalizzate */
  addAggiunte(aggiunte) {
    //fatto così perchè mettendoli sotto non li riconosceva
    const flabel = this.fontLabel
    const fcolor = this.colorLabel
    const fontValue = this.fontValue

    if (aggiunte.length <= 0) {
      return [
        { text: '', border: [false, false, false, false] },
        { text: '', border: [false, false, false, false] },
      ]
    }

    const vitamineBody = []
    const oligoelementiBody = []

    aggiunte.forEach((element) => {
      switch (element.tipo) {
        case TipoAggiunta.Vitamine:
          vitamineBody.push([
            {
              text: this.appGen.isNullOrUndefined(element.aggiunta)
                ? ''
                : element.aggiunta,
              fontSize: flabel,
              color: fcolor,
            },
            {
              text: this.appGen.isNullOrUndefined(element.quantita)
                ? 0
                : element.quantita + ' ml',
              fontSize: fontValue,
            },
          ])
          break
        case TipoAggiunta.Oligoelementi:
          oligoelementiBody.push([
            {
              text: this.appGen.isNullOrUndefined(element.aggiunta)
                ? ''
                : element.aggiunta,
              fontSize: flabel,
              color: fcolor,
            },
            {
              text: this.appGen.isNullOrUndefined(element.quantita)
                ? 0
                : element.quantita + ' ml',
              fontSize: fontValue,
            },
          ])
          break

        default:
          break
      }
    })

    if (oligoelementiBody.length <= 0) {
      oligoelementiBody.push([
        { text: '', border: [false, false, false, false] },
        { text: '', border: [false, false, false, false] },
      ])
    }

    return [
      {
        table: {
          widths: ['auto', 'auto'],
          body: vitamineBody,
        },
        layout: {
          defaultBorder: false,
        },
      },
      {
        table: {
          widths: ['auto', 'auto'],
          body: oligoelementiBody,
        },
        layout: {
          defaultBorder: false,
        },
      },
    ]
  }

