  createBodyVisitaControllo(data, kcalNascoste = false) {
    const leftColumn = []

    //colonne laterali
    leftColumn.push(this.intestazioneMediciLaterale())

    //colonne centrali come le altre ad esempio anamnesi
    this.getInfoPaziente(data)
    this.getInfoVisita(data)
    if (!this.appGen.isNullOrUndefined(data.tutore)) {
      if (data.tutore.length > 0) {
        this.getTutoriMinorenne(data)
      }
    } // leftColumn.push(this.getQrCode(data))

    this.createContentRefertoVisitaControllo(data, kcalNascoste)
    this.bodyContent.push(this.createFooterGenericoFirma(data))
    return this.generateTableBody(leftColumn, this.bodyContent)
  }

  createBody(data, kcalNascoste = false) {
    const leftColumn = []

    //colonne laterali
    leftColumn.push(this.intestazioneMediciLaterale())

    //colonne centrali come le altre ad esempio anamnesi
    this.getInfoPaziente(data)
    this.getInfoVisita(data)
    if (!this.appGen.isNullOrUndefined(data.tutore)) {
      if (data.tutore.length > 0) {
        this.getTutoriMinorenne(data)
      }
    }

    this.createContentReferto(data, kcalNascoste)
    this.bodyContent.push(this.createFooterGenericoFirma(data))
    return this.generateTableBody(leftColumn, this.bodyContent)
  }


