  createContentRefertoVisitaControllo(data, kcalNascoste) {
    this.getAnamnesi(data)
    if (!this.appGen.isNullOrUndefined(data.anamnesiAlimentare)) {
      this.getAnamnesiAlimentare(data, false, kcalNascoste)
    }

    if (data.mnaNrsKarnofskyMust) {
      let exist = false

      if (data.mnaNrsKarnofskyMust.valutazioneScreening !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.valutazioneGlobale !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.valutazioneTotale !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.karnofsky !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.nrs !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.valutazioneTotaleMust !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.rischioMalnutrizioneMust !== null) {
        exist = true
      }
      if (exist) {
        this.getmnaNrsKarnofskyMust(data)
      }
    }

    this.getValutazioneNutrizionale(data)

    switch (data.visita.idTipoAlimentazione) {
      case this.tipoAlimentazione.Artificiale:
        this.getNutrizioneArtificiale(data, kcalNascoste)
        // this.getProdottiArtificiale(data)
        break
      case this.tipoAlimentazione.NaturaleMista:
        this.getNutrizioneNaturale(data, kcalNascoste)
        // this.getDiagnosi(data)
        // this.getProdottiNaturale(data)
        break

      default:
        break
    }
    this.getDiagnosi(data)
  }

