  createContentReferto(data, kcalNascoste) {
    this.getAnamnesi(data)
    if (!this.appGen.isNullOrUndefined(data.anamnesiAlimentare)) {
      this.getAnamnesiAlimentare(data, false, kcalNascoste)
    }

    if (data.mnaNrsKarnofskyMust) {
      let exist = false

      if (data.mnaNrsKarnofskyMust.valutazioneScreening !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.valutazioneGlobale !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.valutazioneTotale !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.karnofsky !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.nrs !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.valutazioneTotaleMust !== null) {
        exist = true
      }
      if (data.mnaNrsKarnofskyMust.rischioMalnutrizioneMust !== null) {
        exist = true
      }
      if (exist) {
        this.getmnaNrsKarnofskyMust(data)
      }
    }
    this.getValutazioneNutrizionale(data)

    switch (data.visita.idTipoAlimentazione) {
      case this.tipoAlimentazione.Artificiale:
        this.getNutrizioneArtificiale(data, kcalNascoste)
        // this.getProdottiArtificiale(data)
        break
      case this.tipoAlimentazione.NaturaleMista:
        this.getNutrizioneNaturale(data, kcalNascoste)
        // this.getProdottiNaturale(data)
        break

      default:
        break
    }

    this.getDiagnosi(data)
  }

  getIntegratori(data) {
    const value = []
    for (const item of data.integratori) {
      value.push(item)
    }

    const table = {
      table: {
        headerRows: 1,
        widths: ['*', '*'],

        body: this.buildTableBodyIntegratori(value),
      },
      layout: {
        hLineColor: '#00afa6',
        vLineColor: '#00afa6',
      },
    }

    this.bodyContent.push(table)
  }

  buildTableBodyIntegratori(data) {
    const fontValue = this.fontValue

    const body = []

    body.push([
      {
        text: 'Integratori',
        style: 'subheader',
        colSpan: 2,
        fontSize: this.fontLabelTitle,
        fillColor: this.fillColorTitle,
        color: this.colorTitle,
        bold: true,
        margin: [0, 5, 0, 5],
        border: [false, false, false, false],
      },
      {},
    ])

    // body.push(columns);
    body.push([
      {
        text: 'Prodotto',
        alignment: 'left',
        color: this.colorLabel,
        fontSize: this.fontLabel,
      },
      {
        text: 'Confezioni',
        alignment: 'left',
        color: this.colorLabel,
        fontSize: this.fontLabel,
      },
    ])
    data.forEach(function (row) {
      const dataRow = []
      dataRow.push(
        { text: row.prodotto, alignment: 'left', fontSize: fontValue },
        { text: row.confezioni, alignment: 'left', fontSize: fontValue }
      )

      body.push(dataRow)
    })
    return body
  }

