  getAnamnesi(data) {
    this.getQuesitoDiagnostico(data)
    if (data.anamnesi) {
      this.getFamiliare(data)

      this.getFisiologica(data)
      this.getPatologicaProssima(data)
      this.getPatologicaRemota(data)

      this.getTerapie(data)
      this.getAllergieIntolleranze(data)
      this.getAttivitaMotorie(data)
      this.getInterventi(data)
      this.getDipendenze(data)
    }
  }

  getQuesitoDiagnostico(data) {
    const body = {
      margin: [0, 0, 0, 5],
      style: 'tableExample',
      unbreakable: true,
      table: {
        // dontBreakRows: true,
        widths: ['100%'],
        body: [
          [
            {
              text: 'Quesito diagnostico ',
              style: 'subheader',
              fontSize: this.fontLabelTitle,
              fillColor: this.fillColorTitle,
              color: this.colorTitle,
              bold: true,
              margin: [0, 5, 0, 5],
              border: [false, false, false, false],
            },
          ],
          [
            {
              text: data.motivoRichiesta ? data.motivoRichiesta : '-',
              style: 'subheader',
              fontSize: 9,
              border: false,
              margin: [0, 5, 0, 5],
            },
          ],
        ],
      },
      layout: {
        hLineColor: '#00afa6',
        vLineColor: '#00afa6',
      },
    }

    this.bodyContent.push(body)
  }

  getFamiliare(data) {
    // //fatto così perchè mettendoli sotto non li riconosceva
    const fontValue = this.fontValue
    const fontLabel = this.fontLabel
    const colorLabel = this.colorLabel

    if (data.anamnesi.familiare.length > 0) {
      const bodyAnamnesi = []
      for (const anamnesi of data.anamnesi.familiare) {
        bodyAnamnesi.push([
          {
            text: anamnesi.gradoParentela + ': ',
            fontSize: fontLabel,
            color: colorLabel,
          },
          { text: anamnesi.patologia, fontSize: fontValue },
        ])
      }

      const content = {
        header: 'simple text',

        margin: [0, 0, 0, 5],
        style: 'tableExample',

        table: {
          widths: ['100%'],
          body: [
            [
              {
                text: 'Anamnesi familiare',
                style: 'subheader',
                fontSize: this.fontLabelTitle,
                fillColor: this.fillColorTitle,
                color: this.colorTitle,
                bold: true,
                margin: [0, 5, 0, 5],
                border: [false, false, false, false],
              },
            ],
            [
              {
                table: {
                  widths: ['*', '310'],
                  body: bodyAnamnesi,
                },
                layout: {
                  defaultBorder: false,
                },
              },
            ],
          ],
        },
        layout: {
          hLineColor: '#00afa6',
          vLineColor: '#00afa6',
        },
      }

      this.bodyContent.push(content)
    }
  }

