  getNutrizioneNaturale(val, kcalNascoste) {
    const data = val.nutrizione;
    /**
     * COLONNA 1
     */
    const col1 = []
    if (!this.appGen.isNullOrUndefined(val.visita.tipoalimentazione)) {
      col1.push([
        {
          text: 'Tipo di alimentazione: ',
          fontSize: this.fontLabel,
          color: this.colorLabel,
        },
        {
          text: val.visita.tipoalimentazione,
          alignment: 'left',
          fontSize: this.fontValue,
        },
      ])
    }
    if (!this.appGen.isNullOrUndefined(data.kcal)) {
      col1.push([
        { text: 'Kcal/die: ', fontSize: this.fontLabel, color: this.colorLabel },
        {
         text: kcalNascoste === true?  '-' : data.kcal + ' kcal', alignment: 'left',
         fontSize: this.fontValue
        },
      ])
    }
    if (!this.appGen.isNullOrUndefined(data.proteine)) {
      col1.push([
        { text: 'Proteine/die: ', fontSize: this.fontLabel, color: this.colorLabel },
        { text: data.proteine + ' g', alignment: 'left', fontSize: this.fontValue },
      ])
    }

    /**
     * COLONNA 2
     */
    const col2 = []
    if (!this.appGen.isNullOrUndefined(data.carboidrati)) {
      col2.push([
        { text: 'Carboidrati: ', fontSize: this.fontLabel, color: this.colorLabel },
        { text: data.carboidrati + ' g', alignment: 'left', fontSize: this.fontValue },
      ])
    }
    if (!this.appGen.isNullOrUndefined(data.lipidi)) {
      col2.push([
        { text: 'Lipidi: ', fontSize: this.fontLabel, color: this.colorLabel },
        { text: data.lipidi + ' g', alignment: 'left', fontSize: this.fontValue },
      ])
    }
    if (!this.appGen.isNullOrUndefined(data.apportoIdrico)) {
      col2.push([
        { text: 'Apporto idrico: ', fontSize: this.fontLabel, color: this.colorLabel },
        { text: data.apportoIdrico + ' ml', alignment: 'left', fontSize: this.fontValue },
      ])
    }

    //altrimenti da errore sulla lenght della tabella di pdfmake quindi controllo che sia vuota la colonna e nel caso aggiunto una riga
    if (col2.length <= 0) {
      col2.push([{}, {}])
    }
    if (col1.length <= 0) {
      col1.push([{}, {}])
    }

    const nutrizione = {
      header: 'simple text',

      margin: [0, 0, 0, 5],
      style: 'tableExample',
      unbreakable: true,
      table: {
        // dontBreakRows: true,
        widths: ['*', '*'],
        body: [
          [
            {
              text: 'Prescrizione',
              colSpan: 2,
              style: 'subheader',
              fontSize: this.fontLabelTitle,
              fillColor: this.fillColorTitle,
              color: this.colorTitle,
              bold: true,
              margin: [0, 5, 0, 5],
              border: [false, false, false, false],
            },
            {},
          ],
          [
            {
              table: {
                widths: ['auto', 'auto'],
                body: col1,
              },
              layout: {
                defaultBorder: false,
              },
            },

            {
              table: {
                widths: ['auto', 'auto'],
                body: col2,
              },
              layout: {
                defaultBorder: false,
              },
            },
          ],
        ],
      },
      layout: {
        hLineColor: '#00afa6',
        vLineColor: '#00afa6',
      },
    }

    this.bodyContent.push(nutrizione)
  }

