  createRefertoPianoTerapeutico(data) {
    const pdf = this.generatePdf(this.createBodyPianoTerapeutico(data))
    pdf.getBase64((file) => {
      this.saveToServer(file, data.idDocumento)
      this.print(pdf)
    })
  }

